INSERT INTO `articles` VALUES (74, 10021, 220, '1', '1', '1', '2025-11-14 22:52:00', '<p>1456789784565897</p><p><br></p><p><br></p>', '已发布', '2025-11-14 14:53:00');
INSERT INTO `articles` VALUES (75, 10021, 231, '啊', '1789', '456', NULL, '<p><span style=\"color: rgb(44, 62, 80); background-color: rgb(255, 255, 255); font-size: 16px; font-family: 宋体;\"> &nbsp; &nbsp;习近平强调，中方支持突尼斯走符合自身国情的发展道路，支持突方独立自主推进改革进程，将命运牢牢掌握在自己手中。中方愿同突方加强发展战略对接，深化基础设施建设、新能源等领域合作，培育医疗卫生、绿色发展、水资源、农业等领域合作新动能，推动两国高质量共建“一带一路”取得更多成果，欢迎更多突尼斯优质特色产品进入中国市场。中方愿继续向突尼斯派遣高水平医疗队，同突方深化教育、旅游等领域合作，密切人文交流。双方要同“全球南方”国家一道，加强团结协作，践行真正的多边主义，倡导平等有序的世界多极化和普惠包容的经济全球化，实现共同发展。中方愿同突方一道努力，建好中阿合作论坛、中非合作论坛，为中阿关系发展注入新动力，携手构建高水平中非命运共同体。</span></p>', '拒绝', NULL);
INSERT INTO `articles` VALUES (76, 10021, 269, '陆军政治工作部干部局就陆军交通中转站相关政策答记者问', '西方来源', '刘晓', '2025-11-19 06:39:32', '<p style=\"text-indent: 2em; text-align: start;\"><strong>编者按</strong></p><p style=\"text-indent: 2em; text-align: start;\"><span style=\"font-family: 楷体;\">2月12日，中国陆军网、中国陆军公众号联合发布《陆军依托现有招接待机构建立交通中转站，官兵和家属福利来啦》一文，受到了广大网友的关注。部队保障服务水平，直接关系到官兵和家属的切身利益。近日，记者专访了陆军政治工作部干部局科干福利处处长王鹏，就网友们关注的热点问题进行了咨询——</span></p><p style=\"text-indent: 2em; text-align: start;\"><strong>问：陆军现役人员本人或其直系亲属入住时，除需提供相关证件外，为什么还要由团级以上政治工作机关出具审批手续？</strong></p><p style=\"text-indent: 2em; text-align: start;\"><strong>答：</strong>相关审批规定主要是为了规范运行、便于核查、利于管理。受中转站数量、承接能力和运营中的管理力量限制，建立必要的审批程序，有利于让更多符合条件的官兵及亲属享受这一政策带来的优待优惠，避免发生非军队人员等不符合条件对象不当得利，侵占优待资源。根据大家的建议,我们决定陆军现役人员入住中转站,可不再提供审批证明,凭有效军人证件即可办理入住,但归队后应向所在单位及时备案,以便于我们宏观统计信息数据,更好地为官兵服务。官兵亲属入住中转站仍需办理审批手续,我们将积极回应官兵诉求，督促指导各单位简化报审程序、缩短批复时间，最大限度方便广大官兵。</p><p style=\"text-indent: 2em; text-align: start;\"><strong>问：陆军军校学员和国防生也十分关注此项保障服务是否可以惠及自身，如果他们可以享受此福利，在入住前是否也需要经过所在学校审批？</strong></p><p style=\"text-indent: 2em; text-align: start;\"><strong>答：</strong>陆军院校学员属于陆军现役人员，凭有效军人证件即可入住交通中转站。在校国防生，属陆军签约高校的，经驻校选培办审批，也可享受此项优待。</p><p style=\"text-indent: 2em; text-align: start;\"><strong>问：有些网友提出，部分交通中转站标准间住宿指导价高于该单位对外营业网上公布价格。针对此种情况，如何保证相关人员入住时享受到真正的福利和实惠呢？</strong></p><p style=\"text-indent: 2em; text-align: start;\"><strong>答：</strong>首先，通知明确陆军交通中转站所定价格，是前期各招接待机构在综合核算运营成本基础确定的标准间指导价格（平均低于市场价40.7%），各中转站向符合入住条件人员收费标准不得高于指导价。各站点将根据市场因素，确定不同时期的收费价格，但均不得高于陆军确定的指导价。其次，经过向相关保障单位了解核实，网上公布价格低于交通中转站指导价的情况，系所在招接待机构为吸引客源，在春节期间推出的特价房型，数量较少。经协调，这些房源也将优先保障陆军军队人员及亲属，部分站点还在此基础上作了进一步优惠，有的已经在网上作了明确。同时，我们也将督促各保障单位进一步优化开支成本、提升管理质效，最大限度压低收费价格，最大诚意让利官兵，保证广大官兵真正得到实惠，这既是我们对保障单位的要求，也是各保障单位的努力方向，请战友们放心。</p><p style=\"text-indent: 2em; text-align: start;\"><strong>问：有些网友反映一些交通中转站地处市郊，交通出行不是很方便。请问在选取交通中转站时，所处地理位置是如何考量和选择的呢？</strong></p><p style=\"text-indent: 2em; text-align: start;\"><strong>答：</strong>一方面，受现有客观条件所限，陆军单位并非在每个大中城市、核心区域都有相应的招接待机构，这也是我们选择中转站之初面临的难题，以北京为例，陆军所属现运行招接待机构，基本在五环以外，区域优势、便捷程度不是很高。另一方面，依据军队全面停止有偿服务规定，部分招接待机构下一步有可能停用，难以纳入交通中转站名单。为此，我们综合考量相关单位的区域环境、保密要求、交通状况等多方面因素，从陆军原有的600余所招接待机构中精心遴选出23所作为首批交通中转站。下步，我们还将根据首批运行情况，结合全军停偿工作进程，拓展交通中转站数量和职能，力争给予广大官兵更多便利和优待。</p><p style=\"text-indent: 2em; text-align: start;\"><strong>问：如果应受保障的军人所在单位不履行政策规定进行审批或拖延审批，以及享受此福利的人员对交通中转站的服务不满意，该如何反映问题呢？</strong></p><p style=\"text-indent: 2em; text-align: start;\"><strong>答：</strong>我们已在通知中明确，如果在审批和入住过程中遇到任何问题，均可向军人所在单位的人力资源部门反映，各单位汇总情况后报我们。我们将对官兵投诉较多、服务保障不到位的单位进行通报曝光，并限期整改。同时，陆军已明确各中转站要完善保障设施、强化服务意识，不得无故拒绝官兵及亲属入住，不得随意提高住宿价格。</p>', '已发布', NULL);
INSERT INTO `articles` VALUES (77, 10021, 219, '中央军委办公厅印发《繁荣发展强军文化实施纲要》', '新华社', '叶梦圆', NULL, '<p style=\"text-indent: 2em; text-align: start;\">新华社北京10月30日电　经中央军委批准，中央军委办公厅日前印发《繁荣发展强军文化实施纲要》（以下简称《实施纲要》）。</p><p style=\"text-indent: 2em; text-align: start;\">《实施纲要》指出，强军事业呼唤强军文化，强军文化汇聚强军力量。在党的科学理论指引下，波澜壮阔的强军实践孕育形成具有我军特色、彰显时代精神、支撑打赢制胜的强军文化，赋予我军自信自强、敢斗善斗、奋进奋发的崭新精神气质。</p><p style=\"text-indent: 2em; text-align: start;\">《实施纲要》明确，强军文化坚守马克思主义军事理论思想精髓，汲取中华优秀传统军事文化特质，以强军思想为灵魂、以强军实践为承载，蕴含着听党指挥、能打胜仗、作风优良的深层精神追求，是新时代政治建军的重要内容，是党领导人民军队创造的先进军事文化新形态。</p><p style=\"text-indent: 2em; text-align: start;\">《实施纲要》强调，繁荣发展强军文化要聚焦用党的创新理论武装全军、教育官兵，着眼培养“四有”革命军人、锻造“四铁”过硬部队，砺志铸魂、砺战激气、砺行厚德，为如期实现建军一百年奋斗目标、加快把人民军队建成世界一流军队提供强大的思想引领力、价值塑造力、精神推动力。要厚植强军文化根和魂，立起强军文化砺战打赢指向，丰富强军文化服务供给，扩大强军文化传播影响。</p><p style=\"text-indent: 2em; text-align: start;\">《实施纲要》要求，各级要强化组织领导，统筹谋划推进。要强固力量支撑，抓好专业队伍、挖潜业余力量。要拓展方法手段，注重科技赋能、官兵参与。要厉行勤俭节约，贯彻艰苦奋斗勤俭建军要求，杜绝奢靡浪费，避免闲置浪费。</p>', '拒绝', NULL);
INSERT INTO `articles` VALUES (78, 10021, 219, '习近平主持召开中央全面深化改革委员会第六次会议', '新闻部', '刘记者', NULL, '<p><br></p><p style=\"text-align: center;\"><span style=\"color: rgb(192, 0, 0);\"><strong>习近平主持召开中央全面深化改革委员会第六次会议强调解放思想实事求是与时俱进求真务实全力抓好改革任务的组织实施李强王沪宁蔡奇出席</strong></span></p><p style=\"text-indent: 2em; text-align: justify;\">新华社北京8月29日电 中共中央总书记、国家主席、中央军委主席、中央全面深化改革委员会主任习近平8月29日上午主持召开中央全面深化改革委员会第六次会议并发表重要讲话。他强调，进一步全面深化改革是在新时代以来全面深化改革基础上推进的，具备坚实基础和有利条件。要运用好已有的改革成果和重要经验，解放思想、实事求是、与时俱进、求真务实，充分调动各方面积极性，全力抓好改革任务的组织实施。</p><p style=\"text-indent: 2em; text-align: justify;\">中共中央政治局常委、中央全面深化改革委员会副主任李强、王沪宁、蔡奇出席会议。</p><p style=\"text-indent: 2em; text-align: justify;\">会议审议通过了《中央和国家机关有关部门贯彻实施党的二十届三中全会〈决定〉重要改革举措分工方案》、《关于实施自由贸易试验区提升战略的意见》等文件。</p><p style=\"text-indent: 2em; text-align: justify;\">会议强调，党的二十届三中全会对进一步全面深化改革作出全面部署，确定了300多项重大改革举措。要坚持党中央对改革的集中统一领导，严格执行请示报告制度。要把准改革的战略重点和优先方向，合理安排改革举措的先后顺序、节奏时机。要把改革同经济社会发展更加紧密结合起来，推动标志性改革举措加快落地。要加强改革系统集成，增强改革政策取向一致性，主动评估对经济社会发展的影响，形成改革和发展的合力。</p><p style=\"text-indent: 2em; text-align: justify;\">会议指出，要优化改革推进落实机制，加强重大问题统筹协调。各牵头单位和参与单位要敢于担当、真抓实干，加强重大改革的调研论证，制定改革组织实施方案。要加强改革督察、评估问效、巡视巡察等工作，以实绩实效和人民群众满意度检验改革。</p><p style=\"text-indent: 2em; text-align: justify;\">会议强调，党的十八大以来，党中央部署设立的22个自由贸易试验区，推出了一大批标志性、引领性制度创新成果，有效发挥了改革开放综合试验平台作用。贯彻落实党的二十届三中全会部署，实施自由贸易试验区提升战略，目的是在更广领域、更深层次开展探索，实现自由贸易试验区制度型开放水平、系统性改革成效、开放型经济质量全面提升。要坚持以高水平开放为引领，以制度创新为核心，鼓励先行先试，开展首创性、集成式探索，推动全产业链创新发展，增强对外贸易综合竞争力，促进投资自由化便利化，推动以贸易、投资、资金流动、交通运输、人员往来自由便利和数据安全有序流动为重点的政策体系更加完善。要统筹发展和安全，稳步扩大规则、规制、管理、标准等制度型开放，提升风险防控能力。</p><p style=\"text-indent: 2em; text-align: justify;\">中央全面深化改革委员会委员出席会议，中央和国家机关有关部门负责同志列席会议。</p>', '拒绝', NULL);
INSERT INTO `articles` VALUES (79, 10021, 219, '习近平主持召开中央全面深化改革委员会第六次会议', '新华社', '王记者', NULL, '<p style=\"text-align: center;\"><span style=\"color: rgb(192, 0, 0);\"><strong>习近平主持召开中央全面深化改革委员会第六次会议强调解放思想实事求是与时俱进求真务实全力抓好改革任务的组织实施李强王沪宁蔡奇出席</strong></span></p><p style=\"text-indent: 2em; text-align: justify;\">新华社北京8月29日电 中共中央总书记、国家主席、中央军委主席、中央全面深化改革委员会主任习近平8月29日上午主持召开中央全面深化改革委员会第六次会议并发表重要讲话。他强调，进一步全面深化改革是在新时代以来全面深化改革基础上推进的，具备坚实基础和有利条件。要运用好已有的改革成果和重要经验，解放思想、实事求是、与时俱进、求真务实，充分调动各方面积极性，全力抓好改革任务的组织实施。</p><p style=\"text-indent: 2em; text-align: justify;\">中共中央政治局常委、中央全面深化改革委员会副主任李强、王沪宁、蔡奇出席会议。</p><p style=\"text-indent: 2em; text-align: justify;\">会议审议通过了《中央和国家机关有关部门贯彻实施党的二十届三中全会〈决定〉重要改革举措分工方案》、《关于实施自由贸易试验区提升战略的意见》等文件。</p><p style=\"text-indent: 2em; text-align: justify;\">会议强调，党的二十届三中全会对进一步全面深化改革作出全面部署，确定了300多项重大改革举措。要坚持党中央对改革的集中统一领导，严格执行请示报告制度。要把准改革的战略重点和优先方向，合理安排改革举措的先后顺序、节奏时机。要把改革同经济社会发展更加紧密结合起来，推动标志性改革举措加快落地。要加强改革系统集成，增强改革政策取向一致性，主动评估对经济社会发展的影响，形成改革和发展的合力。</p><p style=\"text-indent: 2em; text-align: justify;\">会议指出，要优化改革推进落实机制，加强重大问题统筹协调。各牵头单位和参与单位要敢于担当、真抓实干，加强重大改革的调研论证，制定改革组织实施方案。要加强改革督察、评估问效、巡视巡察等工作，以实绩实效和人民群众满意度检验改革。</p><p style=\"text-indent: 2em; text-align: justify;\">会议强调，党的十八大以来，党中央部署设立的22个自由贸易试验区，推出了一大批标志性、引领性制度创新成果，有效发挥了改革开放综合试验平台作用。贯彻落实党的二十届三中全会部署，实施自由贸易试验区提升战略，目的是在更广领域、更深层次开展探索，实现自由贸易试验区制度型开放水平、系统性改革成效、开放型经济质量全面提升。要坚持以高水平开放为引领，以制度创新为核心，鼓励先行先试，开展首创性、集成式探索，推动全产业链创新发展，增强对外贸易综合竞争力，促进投资自由化便利化，推动以贸易、投资、资金流动、交通运输、人员往来自由便利和数据安全有序流动为重点的政策体系更加完善。要统筹发展和安全，稳步扩大规则、规制、管理、标准等制度型开放，提升风险防控能力。</p><p style=\"text-indent: 2em; text-align: justify;\">中央全面深化改革委员会委员出席会议，中央和国家机关有关部门负责同志列席会议。</p>', '拒绝', NULL);
INSERT INTO `articles` VALUES (80, 10021, 226, '啊啊啊', '新闻社', '李继者', NULL, '<p style=\"text-align: center;\"><span style=\"color: rgb(192, 0, 0);\"><strong>习近平主持召开中央全面深化改革委员会第六次会议强调解放思想实事求是与时俱进求真务实全力抓好改革任务的组织实施李强王沪宁蔡奇出席</strong></span></p><p style=\"text-indent: 2em; text-align: justify;\">新华社北京8月29日电 中共中央总书记、国家主席、中央军委主席、中央全面深化改革委员会主任习近平8月29日上午主持召开中央全面深化改革委员会第六次会议并发表重要讲话。他强调，进一步全面深化改革是在新时代以来全面深化改革基础上推进的，具备坚实基础和有利条件。要运用好已有的改革成果和重要经验，解放思想、实事求是、与时俱进、求真务实，充分调动各方面积极性，全力抓好改革任务的组织实施。</p><p style=\"text-indent: 2em; text-align: justify;\">中共中央政治局常委、中央全面深化改革委员会副主任李强、王沪宁、蔡奇出席会议。</p><p style=\"text-indent: 2em; text-align: justify;\">会议审议通过了《中央和国家机关有关部门贯彻实施党的二十届三中全会〈决定〉重要改革举措分工方案》、《关于实施自由贸易试验区提升战略的意见》等文件。</p><p style=\"text-indent: 2em; text-align: justify;\">会议强调，党的二十届三中全会对进一步全面深化改革作出全面部署，确定了300多项重大改革举措。要坚持党中央对改革的集中统一领导，严格执行请示报告制度。要把准改革的战略重点和优先方向，合理安排改革举措的先后顺序、节奏时机。要把改革同经济社会发展更加紧密结合起来，推动标志性改革举措加快落地。要加强改革系统集成，增强改革政策取向一致性，主动评估对经济社会发展的影响，形成改革和发展的合力。</p><p style=\"text-indent: 2em; text-align: justify;\">会议指出，要优化改革推进落实机制，加强重大问题统筹协调。各牵头单位和参与单位要敢于担当、真抓实干，加强重大改革的调研论证，制定改革组织实施方案。要加强改革督察、评估问效、巡视巡察等工作，以实绩实效和人民群众满意度检验改革。</p><p style=\"text-indent: 2em; text-align: justify;\">会议强调，党的十八大以来，党中央部署设立的22个自由贸易试验区，推出了一大批标志性、引领性制度创新成果，有效发挥了改革开放综合试验平台作用。贯彻落实党的二十届三中全会部署，实施自由贸易试验区提升战略，目的是在更广领域、更深层次开展探索，实现自由贸易试验区制度型开放水平、系统性改革成效、开放型经济质量全面提升。要坚持以高水平开放为引领，以制度创新为核心，鼓励先行先试，开展首创性、集成式探索，推动全产业链创新发展，增强对外贸易综合竞争力，促进投资自由化便利化，推动以贸易、投资、资金流动、交通运输、人员往来自由便利和数据安全有序流动为重点的政策体系更加完善。要统筹发展和安全，稳步扩大规则、规制、管理、标准等制度型开放，提升风险防控能力。</p><p style=\"text-indent: 2em; text-align: justify;\">中央全面深化改革委员会委员出席会议，中央和国家机关有关部门负责同志列席会议。</p>', '待审', NULL);
